"""Recognize dangerous GitHub Actions workflow triggers."""

from __future__ import annotations

import os
import re

from finding import finding, finding_location


_TRIGGERS = ("pull_request_target", "workflow_run")


def audit_dangerous_triggers(text: str, filename: str, persona: str = "regular") -> list[dict]:
    lines = text.splitlines(keepends=True)
    starts = []
    offset = 0
    for i, raw in enumerate(lines):
        if re.match(r"^on\s*:", raw):
            starts.append((i, offset))
        offset += len(raw.encode("utf-8"))
    if not starts:
        return []
    row, start = starts[0]
    block_end = len(lines)
    offset = start
    for i in range(row, len(lines)):
        raw = lines[i]
        if i > row and raw.strip() and not raw[0].isspace() and not raw.lstrip().startswith("#"):
            block_end = i
            break
        offset += len(raw.encode("utf-8"))
    # zizmor's source feature excludes the trailing line ending of the block.
    end = offset
    while end > start and text.encode("utf-8")[end - 1:end] in (b"\n", b"\r"):
        end -= 1
    feature = text.encode("utf-8")[start:end].decode("utf-8", errors="replace")
    found = [trigger for trigger in _TRIGGERS if re.search(r"(?m)^\s*(?:-\s*)?" + re.escape(trigger) + r"\s*:", feature) or re.search(r"(?m)^on\s*:\s*[^\n]*\b" + re.escape(trigger) + r"\b", feature)]
    path = os.path.abspath(filename)
    out = []
    for trigger in found:
        loc = finding_location(path, f"{trigger} is almost always used insecurely", ["on"], text, start, end)
        out.append(finding("dangerous-triggers", "use of fundamentally insecure workflow trigger", "High", "Medium", persona.capitalize(), [loc]))
    return out

